import{_ as e,o,c as i,a2 as c}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Práctica 1: Diagnóstico Comunitario y Árbol de Problemas","description":"Ejercicios prácticos y código fuente en JavaScript para Proyecto Sociotecnológico I","frontmatter":{"title":"Práctica 1: Diagnóstico Comunitario y Árbol de Problemas","description":"Ejercicios prácticos y código fuente en JavaScript para Proyecto Sociotecnológico I"},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/ejercicios/I-I/practica-1.md","filePath":"materias/Proyecto_Sociotecnologico_I/ejercicios/I-I/practica-1.md"}'),t={name:"materias/Proyecto_Sociotecnologico_I/ejercicios/I-I/practica-1.md"};function r(n,a,s,d,l,u){return o(),i("div",null,[...a[0]||(a[0]=[c('<h1 id="💻-practica-1-diagnostico-comunitario-y-arbol-de-problemas" tabindex="-1">💻 Práctica 1: Diagnóstico Comunitario y Árbol de Problemas <a class="header-anchor" href="#💻-practica-1-diagnostico-comunitario-y-arbol-de-problemas" aria-label="Permalink to &quot;💻 Práctica 1: Diagnóstico Comunitario y Árbol de Problemas&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📌 Información de Cátedra</p><ul><li><strong>Materia:</strong> Proyecto Sociotecnológico I</li><li><strong>Trimestre:</strong> I-I</li><li><strong>Guía Teórica Vinculada:</strong> <a href="/pnfi-doc/materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_1">Lectura de Cátedra (L1)</a></li></ul></div><hr><h2 id="📋-enunciados-y-actividades-practicas" tabindex="-1">📋 Enunciados y Actividades Prácticas <a class="header-anchor" href="#📋-enunciados-y-actividades-practicas" aria-label="Permalink to &quot;📋 Enunciados y Actividades Prácticas&quot;">​</a></h2><p>Esta guía contiene actividades prácticas para afianzar los conceptos de Sociedad, Comunidad y el rol transformador de la Universidad Politécnica dentro del PNFI.</p><hr><ol><li><p><strong>Mapa Conceptual: Sociedad vs Comunidad</strong> Elabore un mapa conceptual que compare y contraste los conceptos de &quot;Sociedad&quot; y &quot;Comunidad&quot;. Incluya al menos 3 diferencias clave y 2 similitudes. Utilice ejemplos reales de su entorno local (su barrio, su sector, su municipio).</p></li><li><p><strong>Análisis Reflexivo: El Rol del Estudiante PNFI</strong> Redacte un ensayo corto (máximo 1 página) donde explique por qué el estudiante de Informática del PNFI no puede graduarse sin haber ejecutado un proyecto en una comunidad real. Fundamente su respuesta citando al menos un artículo del Reglamento PSI/T de la UPTT.</p></li><li><p><strong>Investigación de Campo: Identificación de Comunidades Potenciales</strong> Identifique 3 comunidades cercanas a su hogar o a la universidad donde podría ejecutarse un Proyecto Sociotecnológico de Informática Aplicada. Para cada una, elabore una ficha técnica que contenga: Nombre de la comunidad, Ubicación geográfica, Tipo de institución (escuela, ambulatorio, consejo comunal) y una breve descripción de posibles necesidades tecnológicas observadas.</p></li><li><p><strong>Debate Grupal: &quot;¿La tecnología resuelve problemas sociales?&quot;</strong> En equipos de 3 personas, preparen argumentos a favor y en contra de la siguiente afirmación: <em>&quot;Llevar computadoras a una comunidad rural resuelve automáticamente el problema de la brecha digital&quot;</em>. Cada equipo debe presentar su posición en 5 minutos.</p></li></ol><hr><hr>',9)])])}const g=e(t,[["render",r]]);export{m as __pageData,g as default};
